public class Solution {
    public int findDerangement(int n) {
        final int MOD = 1000000007;
        long[] dp = new long[n + 1];
        dp[2] = 1;
        for (int i = 3; i <= n; ++i) {
            dp[i] = (i - 1) * (dp[i - 1] + dp[i - 2]) % MOD;
        }
        return (int)dp[n];
    }
}

